package cz.ioff.app;
import android.accessibilityservice.AccessibilityService;import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.os.*;import android.view.*;import android.view.accessibility.AccessibilityEvent;import android.widget.*;import java.util.*;
public class ShieldService extends AccessibilityService{WindowManager wm;View overlay;String blocked;long bypassUntil;final Set<String>d=new HashSet<>(Arrays.asList("com.instagram.android","com.facebook.katana","com.zhiliaoapp.musically","com.google.android.youtube","com.twitter.android","com.reddit.frontpage"));public void onServiceConnected(){wm=(WindowManager)getSystemService(WINDOW_SERVICE);}public void onAccessibilityEvent(AccessibilityEvent e){if(e.getEventType()!=AccessibilityEvent.TYPE_WINDOW_STATE_CHANGED||e.getPackageName()==null)return;String pkg=e.getPackageName().toString();if(pkg.equals(getPackageName()))return;SharedPreferences p=getSharedPreferences("ioff",0);if(!p.getBoolean("shield_enabled",true)||!protectedNow(p)||System.currentTimeMillis()<bypassUntil||!p.getStringSet("blocked_apps",d).contains(pkg))return;blocked=pkg;show(false,true);}boolean protectedNow(SharedPreferences p){if(p.getBoolean("focus_active",false)&&p.getLong("focus_end",0)>System.currentTimeMillis())return true;if(!p.getBoolean("morning_shield",true))return false;Calendar c=Calendar.getInstance();int m=c.get(Calendar.HOUR_OF_DAY)*60+c.get(Calendar.MINUTE);return m>=p.getInt("morning_start",360)&&m<p.getInt("morning_until",540);}int day(SharedPreferences p){return p.getBoolean("focus_active",false)?p.getInt("focus_day",p.getInt("day",1)):p.getInt("day",1);}String app(){if(blocked==null)return"This app";if(blocked.contains("instagram"))return"Instagram";if(blocked.contains("youtube"))return"YouTube";if(blocked.contains("reddit"))return"Reddit";if(blocked.contains("facebook"))return"Facebook";if(blocked.contains("twitter"))return"X";if(blocked.contains("tiktok")||blocked.contains("zhiliao"))return"TikTok";return"This app";}TextView t(String s,int z,int color){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(color);v.setGravity(Gravity.CENTER);v.setPadding(10,12,10,12);return v;}GradientDrawable bg(int c,float r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(r);return g;}void show(boolean confirm,boolean count){remove();SharedPreferences p=getSharedPreferences("ioff",0);LinearLayout b=new LinearLayout(this);b.setOrientation(LinearLayout.VERTICAL);b.setGravity(Gravity.CENTER);b.setPadding(54,80,54,80);b.setBackgroundColor(Color.rgb(8,10,13));b.addView(t("iOff",26,Color.rgb(138,255,181)));b.addView(t(confirm?"Break focus intentionally?":app()+" can wait.",34,Color.rgb(245,247,248)));String goal=p.getString("goal","");long rem=Math.max(0,p.getLong("focus_end",0)-System.currentTimeMillis());String body=confirm?"You've already chosen what matters.":(goal.isEmpty()?"You're in protected time.":"You chose to finish\n“"+goal+"”\n\n"+(rem/60000)+" min remaining");b.addView(t(body,17,Color.rgb(150,157,168)));Button back=new Button(this);back.setText("RETURN TO FOCUS");back.setTextColor(Color.rgb(8,10,13));back.setBackground(bg(Color.rgb(138,255,181),28));back.setOnClickListener(v->{performGlobalAction(GLOBAL_ACTION_BACK);remove();});b.addView(back,new LinearLayout.LayoutParams(-1,120));Button pass=new Button(this);pass.setText(confirm?"CONTINUE FOR 5 MINUTES":"I REALLY NEED "+app().toUpperCase());pass.setTextColor(Color.WHITE);pass.setBackgroundColor(Color.TRANSPARENT);pass.setOnClickListener(v->{if(!confirm){show(true,false);return;}bypassUntil=System.currentTimeMillis()+300000;String k="exp_"+day(p)+"_bypasses";p.edit().putInt(k,p.getInt(k,0)+1).apply();remove();});b.addView(pass,new LinearLayout.LayoutParams(-1,110));int type=Build.VERSION.SDK_INT>=26?WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY:WindowManager.LayoutParams.TYPE_PHONE;WindowManager.LayoutParams lp=new WindowManager.LayoutParams(-1,-1,type,WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN,PixelFormat.TRANSLUCENT);overlay=b;wm.addView(overlay,lp);if(count){String k="exp_"+day(p)+"_shield";p.edit().putInt(k,p.getInt(k,0)+1).apply();}}void remove(){if(overlay!=null){try{wm.removeView(overlay);}catch(Exception ignored){}overlay=null;}}public void onInterrupt(){remove();}public void onDestroy(){remove();super.onDestroy();}}
